/** The Free plan's Browser Run time: 10 minutes a day. The bell rings once at half of it. */
export const BROWSER_DAILY_MS = 600_000;
export const BROWSER_ALERT_MS = BROWSER_DAILY_MS / 2;
/** A run of the sweep enqueues at most this many documents. */
export const SWEEP_LIMIT = 20;
/** A document is swept only once it is older than this (the send route's own enqueue gets the first chance). */
export const SWEEP_GRACE_MS = 600_000;
/** The queue keeps a message for 24 hours; a delay stays an hour under that, so the delayed copy is never lost to retention. */
const MAX_DELAY_S = 82_800;
/** After the daily quota resets at 00:00 UTC, wait this long before trying again. */
const QUOTA_MARGIN_MS = 120_000;

const hex = (b: ArrayBuffer) =>
  Array.from(new Uint8Array(b), (x) => x.toString(16).padStart(2, "0")).join("");
/** The bell lines of 07-P §4 (word for word). */
export const BELL_COPY = {
  failed: (number: string, version: number) =>
    `The PDF for ${number} v${version} could not be made. Open it to try again.`,
  /** An invoice has one version: the same line without "v1" (07-R §5 has "The PDF couldn't be made. Try again." for the screen; the bell keeps 07-P's shape). */
  failedInvoice: (number: string) => `The PDF for ${number} could not be made. Open it to try again.`,
  /** A PDF that failed its integrity check (07-Q Q9, owner 2026-10-26): it was not sent; the same check would fail again, so a person looks. */
  integrity: (label: string) =>
    `The PDF of ${label} didn't match its saved copy, so it wasn't sent. A developer needs to look at it before it can be sent.`,
  /** An invoice PDF refused at the snapshot or the render (`pdf.refused`): 07-R §3's own line (the PDF was "made", not "sent": an invoice is emailed by a person later). */
  invoiceRefused: (label: string) =>
    `The PDF of ${label} didn't match its saved copy, so it wasn't made. A developer needs to look at it.`,
  /** An invoice whose frozen signature image can't be used (missing, other bytes, oversized): 07-R §3. The fix is in Settings, not a developer. */
  invoiceSignature: (label: string) =>
    `The signature image couldn't be used for the PDF of ${label}, so the PDF wasn't made. Check the signature in Settings › Company.`,
  /** A credit or debit note, or an invoice for a payment received, issued without the signature it must carry (older staging documents only): 07-ZC line 7
   *  (L7, lead 2026-10-31). The document is frozen, so the fix is not in Settings: a developer looks. */
  invoiceUnsigned: (label: string) =>
    `The PDF of ${label} wasn't made because it was issued without the signature. Credit notes, debit notes and invoices for a payment received always carry it. A developer needs to look at it.`,
  /** FX-1 (A6 2): a document whose PDF failed on `SWEEP_MAX_FAILED_NIGHTS` nights; the nightly retry stops (kind `pdf.refused`). 07-Y item 26 (owner 2026-10-29). */
  stoppedNightly: (label: string) =>
    `The PDF of ${label} couldn't be made on 3 days, so the nightly retry has stopped. A developer needs to look at it.`,
  half: "Half of today's PDF allowance is used.",
  quota: "Today's PDF allowance is used up. Waiting PDFs are made tomorrow.",
} as const;

/** What a bell calls a document: its number, else "Untitled" (a sent version always has a number; this is the safety net). Never the title: a staff-typed title can hold a client name, and a bell outlives an anonymised client (07-Q, lead 2026-10-26). */
export const documentLabel = (number: string | null): string => number?.trim() || "Untitled";

export const sha256Bytes = async (bytes: Uint8Array): Promise<string> =>
  hex(await crypto.subtle.digest("SHA-256", bytes));

// ---- the bell and the statistics ---------------------------------------------------------------------------------------------------

const BELL_SQL = `INSERT OR IGNORE INTO notifications (id, user_id, kind, entity_type, entity_id, title, link)
  SELECT 'n_' || lower(hex(randomblob(16))), u.id, ?1, ?2, ?3, ?4, ?5 FROM staff_users u WHERE u.status = 'active' AND u.role = 'owner'`;

const bell = (
  env: Env,
  kind: string,
  entityType: string,
  entityId: string,
  title: string,
  link: string,
): D1PreparedStatement => env.DB.prepare(BELL_SQL).bind(kind, entityType, entityId, title, link);

/** The half-of-the-day bell, written only once the day's total has reached the threshold (`?1` date, `?2` threshold, `?3` title). */
export const HALF_BELL_SQL = `INSERT OR IGNORE INTO notifications (id, user_id, kind, entity_type, entity_id, title, link)
  SELECT 'n_' || lower(hex(randomblob(16))), u.id, 'pdf.browser_half', 'system', ?1, ?3, '/'
  FROM staff_users u WHERE u.status = 'active' AND u.role = 'owner'
    AND (SELECT value FROM stats_daily WHERE date = ?1 AND metric = 'pdf.browser_ms' AND dimension = '') >= ?2`;

/** Adds to one counter of `stats_daily` (`?1` date, `?2` metric, `?3` amount, `?4` time). The dimension is always empty. */
export const STAT_ADD_SQL = `INSERT INTO stats_daily (date, metric, dimension, value, updated_at) VALUES (?1, ?2, '', ?3, ?4)
  ON CONFLICT(date, metric, dimension) DO UPDATE SET value = value + excluded.value, updated_at = excluded.updated_at`;

export const stat = (env: Env, date: string, metric: string, amount: number, now: number) =>
  env.DB.prepare(STAT_ADD_SQL).bind(date, metric, amount, now);

// ---- R2: write once -------------------------------------------------------------------------------------------------------------------

/**
 * Writes an object that must never be replaced. A `head` first (a cheap miss), then a put that fails if the key exists (`If-None-Match: *`,
 * R2 `onlyIf`). `existing` hands back the object that was already there.
 */
export async function putOnce(
  bucket: R2Bucket,
  key: string,
  body: string | Uint8Array,
  contentType: string,
  /** Lowercase hex SHA-256 of `body`: R2 refuses the write when the bytes it received hash differently. */
  sha256?: string,
): Promise<{ created: true } | { created: false; existing: R2ObjectBody }> {
  if ((await bucket.head(key)) === null) {
    const put = await bucket.put(key, body, {
      httpMetadata: { contentType },
      onlyIf: { etagDoesNotMatch: "*" },
      ...(sha256 === undefined ? {} : { sha256 }),
    });
    if (put !== null) return { created: true };
  }
  const existing = await bucket.get(key);
  if (existing === null) throw new Error("r2: the put was refused but no object is there");
  return { created: false, existing };
}

/**
 * Stores rendered PDF bytes write-once and returns the stored file and its SHA-256, hashing the rendered bytes once (audit A6, finding 5):
 * the same hash goes to R2 (which refuses bytes that differ) and to the row. When another render got there first, that file and its hash.
 */
export async function putPdfOnce(
  bucket: R2Bucket,
  key: string,
  rendered: Uint8Array,
): Promise<{ bytes: Uint8Array; sha256: string }> {
  const sha256 = await sha256Bytes(rendered);
  const stored = await putOnce(bucket, key, rendered, "application/pdf", sha256);
  if (stored.created) return { bytes: rendered, sha256 };
  const existing = new Uint8Array(await stored.existing.arrayBuffer());
  return { bytes: existing, sha256: await sha256Bytes(existing) };
}

// ---- snapshot --------------------------------------------------------------------------------------------------------------------------

export type SnapshotOutcome = "queued" | "skipped" | "refused";

/** Handles one `pdf.snapshot` message. Throws for anything a retry can fix (D1, R2, the queue); returns for everything else. */
export async function processSnapshot(env: Env, msg: PdfSnapshotMessage): Promise<SnapshotOutcome> {
  const bundle = bundleOf<TermsRow>(await env.DB.batch(loadStatements(env.DB, msg.documentId)));
  if (!bundle) return skip("not_found");
  const d = bundle.document;
  const label = documentLabel(d.number_display);
  if (d.pdf_sha256 !== null) return skip("done");
  // An erased client takes nothing new: no envelope, no PDF, no bell (the standing rule for anonymised clients; Researched 2026-10-28, DPDP Act s.8(7) and s.12(3) (08-C RB-11)).
  if (await clientIsGone(env, d.client_id)) return skip("client_gone");
  // T7: an offer whose personal details were erased is never snapshotted, rendered or verified again: no object, no bell (Settled by the lead on the safest reading, 2026-10-30 (08-C RB-37)).
  if ((d.redacted_at ?? null) !== null) return skip("redacted");
  if (isInvoiceFlowType(d.type)) return snapshotInvoice(env, msg, bundle, label);
  const made = await envelopeOfBundle(bundle);
  if (!made.ok) {
    if (made.code === "unsupported_type" || made.code === "not_sent") return skip(made.code);
    // The rows do not reproduce what the send route sealed: nothing is written, the owners are told, and a retry cannot help.
    logEvent("pdf.refused", { stage: "snapshot", code: made.code });
    await env.DB.batch([
      bell(env, "pdf.failed", "document", d.id, BELL_COPY.integrity(label), `/proposals/${d.id}`),
    ]);
    return "refused";
  }
  const e = made.envelope;
  const keys = pdfKeys({ type: e.type, fy: e.fy, number: e.number, version: e.version });
  const text = serializeEnvelope(e);
  const put = await putOnce(env.DOCS, keys.snapshot, text, "application/json");
  if (!put.created && (await put.existing.text()) !== text) {
    // A different envelope already holds the key: never overwritten, never rendered from; a person looks.
    logEvent("pdf.refused", { stage: "snapshot", code: "key_conflict" });
    await env.DB.batch([
      bell(env, "pdf.failed", "document", d.id, BELL_COPY.integrity(label), `/proposals/${d.id}`),
    ]);
    return "refused";
  }
  const saved = await env.DB.prepare(
    "UPDATE documents SET snapshot_r2_key = ?2 WHERE id = ?1 AND snapshot_r2_key IS NULL AND redacted_at IS NULL",
  )
    .bind(d.id, keys.snapshot)
    .run();
  // T7: redacted while the envelope was being stored: the object just stored goes, and nothing follows.
  if (saved.meta.changes === 0 && (await isRedacted(env, d.id))) {
    await env.DOCS.delete(keys.snapshot);
    return skip("redacted");
  }
  await env.PDF_QUEUE.send({ v: 1, kind: "pdf.render", documentId: d.id, hop: 0 } satisfies PdfRenderMessage);
  logEvent("pdf.snapshot", { reason: msg.reason, created: put.created });
  return "queued";
}

// ---- the invoice family (B2) --------------------------------------------------------------------------------------------------------

/** The bell of a refused invoice envelope or signature: its own kind (the sweep leaves a document with one alone), and the invoice's page. */
const refusedBell = (env: Env, id: string, label: string): D1PreparedStatement =>
  bell(env, "pdf.refused", "document", id, BELL_COPY.invoiceRefused(label), `/invoices/${id}`);

/** `snapshot` for an issued invoice: the same steps as a proposal's, from the invoice envelope. */
async function snapshotInvoice(
  env: Env,
  msg: PdfSnapshotMessage,
  bundle: NonNullable<ReturnType<typeof bundleOf<TermsRow>>>,
  label: string,
): Promise<SnapshotOutcome> {
  const d = bundle.document;
  const made = await invoiceEnvelopeOfBundle(bundle);
  if (!made.ok) {
    if (made.code === "unsupported_type" || made.code === "not_issued") return skip(made.code);
    // The rows do not reproduce what the issue sealed: nothing is written, the owners are told, and a retry cannot help.
    logEvent("pdf.refused", { stage: "snapshot", code: made.code, family: "invoice" });
    await env.DB.batch([refusedBell(env, d.id, label)]);
    return "refused";
  }
  const e = made.envelope;
  const keys = pdfKeys({ type: e.type, fy: e.fy, number: e.number, version: 1 });
  const text = serializeInvoiceEnvelope(e);
  const put = await putOnce(env.DOCS, keys.snapshot, text, "application/json");
  if (!put.created && (await put.existing.text()) !== text) {
    // A different envelope already holds the key: never overwritten, never rendered from; a person looks.
    logEvent("pdf.refused", { stage: "snapshot", code: "key_conflict", family: "invoice" });
    await env.DB.batch([refusedBell(env, d.id, label)]);
    return "refused";
  }
  await env.DB.prepare("UPDATE documents SET snapshot_r2_key = ?2 WHERE id = ?1 AND snapshot_r2_key IS NULL")
    .bind(d.id, keys.snapshot)
    .run();
  await env.PDF_QUEUE.send({ v: 1, kind: "pdf.render", documentId: d.id, hop: 0 } satisfies PdfRenderMessage);
  logEvent("pdf.snapshot", { reason: msg.reason, created: put.created, family: "invoice" });
  return "queued";
}

/** The largest signature image the Settings route accepts (core `SIGNATURE_MAX_BYTES`; a test keeps the two equal). */
export const SIGNATURE_MAX_BYTES = 256 * 1024;
/** Where the Settings route writes a signature: content-addressed, so a key of any other shape is never read. */
const SIGNATURE_KEY = /^settings\/signature-[0-9a-f]{16}\.(png|jpg)$/;
const SIGNATURE_MIMES = ["image/png", "image/jpeg"];

/**
 * The signature image of an invoice, verified: read from DOCS by the key frozen in the envelope, its size within the cap and its SHA-256 the frozen
 * one. `null` is "this invoice has no signature"; `"refused"` is a signature that is frozen but cannot be shown as it was (the object is missing,
 * another size, other bytes, an unexpected key or type): the invoice is not rendered without it (LD11; Researched 2026-10-28, Rule 46 CGST Rules (08-C RA-05)).
 */
async function verifiedSignature(
  env: Env,
  e: InvoiceEnvelope,
): Promise<{ mime: string; base64: string } | null | "refused"> {
  const ref = e.snapshot.header.issuer.signature;
  if (ref === null) return null;
  if (!SIGNATURE_KEY.test(ref.key) || !SIGNATURE_MIMES.includes(ref.mime)) return "refused";
  // One read: the object's size is known before its body is, so an oversized one is never read.
  const object = await env.DOCS.get(ref.key);
  if (object === null || object.size < 1 || object.size > SIGNATURE_MAX_BYTES) return "refused";
  const bytes = new Uint8Array(await object.arrayBuffer());
  if (bytes.byteLength > SIGNATURE_MAX_BYTES || !(await verifySignatureBytes(e, bytes))) return "refused";
  return { mime: ref.mime, base64: toBase64(bytes) };
}

/** `render` for an issued invoice (the common steps are `processRender`'s). Returns the outcome; throws for anything a retry can fix. */
async function renderInvoice(
  env: Env,
  msg: PdfRenderMessage | PdfSupplierMessage,
  row: RenderRow,
  envelopeText: string,
  now: number,
  clock: Clock,
  htmlOf: HtmlOf,
  /** `supplier`: the stored DUPLICATE FOR SUPPLIER copy (Q11): the same frozen envelope, the other copy mark, its own key; no row is written, nothing is emailed. */
  copy: "recipient" | "supplier" = "recipient",
): Promise<RenderOutcome> {
  const envelope = parseInvoiceEnvelope(envelopeText);
  const verdict =
    envelope === null
      ? ({ ok: false, code: "shape" } as const)
      : envelope.documentId !== row.id || envelope.snapshotSha256 !== row.snapshot_sha256
        ? ({ ok: false, code: "row_mismatch" } as const)
        : await verifyInvoiceEnvelope(envelope);
  const label = documentLabel(row.number_display);
  if (!envelope || !verdict.ok) {
    logEvent("pdf.refused", {
      stage: "render",
      code: verdict.ok ? "unknown" : verdict.code,
      family: "invoice",
    });
    await env.DB.batch([refusedBell(env, row.id, label)]);
    return "refused";
  }
  const keyInput = { type: envelope.type, fy: envelope.fy, number: envelope.number, version: 1 };
  const keys = pdfKeys(keyInput);
  const target = copy === "supplier" ? supplierPdfKey(keyInput) : keys.pdf;

  // A PDF stored by an earlier run whose row update was lost: the first one stays, a document is never rendered twice.
  const already = await env.DOCS.get(target);
  if (already !== null) {
    if (copy === "recipient")
      await settle(
        env,
        row,
        keys.pdf,
        await sha256Bytes(new Uint8Array(await already.arrayBuffer())),
        { renders: 0, browserMs: 0 },
        now,
      );
    logEvent("pdf.adopted", { family: "invoice", copy });
    return "adopted";
  }

  // T4 (rt2, L4): a credit or debit note, or an invoice for a payment received, is never rendered without the signature it must carry (Researched 2026-10-30, Rule 53(1A)
  // CGST Rules (08-C RA-22); s.31(3)(d) CGST Act and Rule 50 CGST Rules (08-C RA-17)). Checked after the adoption above, so a PDF already stored stays; an older staging
  // document issued before the rule is refused here (one bell, no retry: the frozen envelope would print the same page). The fix is not in Settings (the document is
  // frozen), so the bell is its own line (07-ZC line 7, L7) with the invoice's page.
  // The supplier copy of such a document whose recipient PDF is already stored (`pdf_sha256` set, made before the rule) is not refused (code review 1): it is
  // the supplier's own record of a page that already exists, the same frozen envelope, so refusing it would only ring the bell at every ask and never store it.
  if (signatureMissing(envelope) && !(copy === "supplier" && row.pdf_sha256 !== null)) {
    logEvent("pdf.refused", {
      stage: "render",
      code: "signature_required",
      family: "invoice",
      type: envelope.type,
    });
    await env.DB.batch([
      bell(env, "pdf.refused", "document", row.id, BELL_COPY.invoiceUnsigned(label), `/invoices/${row.id}`),
    ]);
    return "refused";
  }
  const signature = await verifiedSignature(env, envelope);
  if (signature === "refused") {
    logEvent("pdf.refused", { stage: "render", code: "signature", family: "invoice" });
    // Same kind (the sweep leaves it alone), but its own line and the place to fix it (07-R §3).
    await env.DB.batch([
      bell(env, "pdf.refused", "document", row.id, BELL_COPY.invoiceSignature(label), "/settings/company"),
    ]);
    return "refused";
  }
  // the generic portal address (the host of PORTAL_URL), never a personal link; unset leaves the "pay in the portal" line out
  const view = toInvoiceView(envelope, viewConfigFor(env.PORTAL_URL), {
    signature,
    portalLink: portalHost(env.PORTAL_URL),
    copy,
  });
  const html = htmlOf(view);
  // LD33 (M5.2): an export invoice prints its frozen endorsement and a proforma its frozen notice, byte for byte, or nothing is rendered (the owners'
  // bell rings once, the message is acknowledged without a retry: a retry would print the same page). LD54 (M5.3): a credit or debit note names the invoice it
  // is against (the frozen number as one text node of its own), or nothing is rendered the same way (Rule 53(1A); Researched 2026-10-28, Rule 46 CGST Rules (08-C RA-05)).
  const missing = missingStatutoryLine(envelope, html);
  if (missing !== null) {
    logEvent("pdf.refused", {
      stage: "render",
      code: `statutory_${missing}`,
      family: "invoice",
      type: envelope.type,
    });
    await env.DB.batch([refusedBell(env, row.id, label)]);
    return "refused";
  }
  const result = await renderPaced(env, html, pdfOptionsFor(view), clock);
  if (!result.ok) return failed(env, msg, result, now);

  const { bytes, sha256 } = await putPdfOnce(env.DOCS, target, result.bytes);
  if (copy === "supplier") {
    // The copy is the supplier's own record: no row names it and nobody is told; the Browser Run time it used is counted like any render.
    const date = dayOf(now);
    await env.DB.batch([
      stat(env, date, "pdf.renders", 1, now),
      stat(env, date, "pdf.browser_ms", result.browserMs, now),
      env.DB.prepare(HALF_BELL_SQL).bind(date, BROWSER_ALERT_MS, BELL_COPY.half),
    ]);
  } else {
    await settle(env, row, keys.pdf, sha256, { renders: 1, browserMs: result.browserMs }, now);
  }
  logEvent("pdf.rendered", {
    bytes: bytes.byteLength,
    browserMs: result.browserMs,
    hop: msg.hop,
    family: "invoice",
    copy,
  });
  return "rendered";
}

/**
 * Handles one `pdf.supplier` message (Q11, Rule 48(2)): the DUPLICATE FOR SUPPLIER copy of an issued tax invoice, export invoice, credit note or debit note, rendered from the SAME
 * frozen envelope as the original (so only after the original's PDF exists), with every check the original has, and stored write-once under its own key. A proforma has none.
 * A client that was anonymised takes no PDF at all (the standing rule).
 */
export async function processSupplierCopy(
  env: Env,
  msg: PdfSupplierMessage,
  now = Date.now(),
  clock: Clock = realClock,
  htmlOf: HtmlOf = renderDocumentHtml,
): Promise<RenderOutcome> {
  const row = await env.DB.prepare(RENDER_ROW_SQL).bind(msg.documentId).first<RenderRow>();
  if (!row || row.frozen_at === null || !hasSupplierCopy(row.type)) {
    logEvent("pdf.supplier_skipped", { why: row ? "not_supported" : "not_found" });
    return "skipped";
  }
  if (row.client_gone) {
    logEvent("pdf.supplier_skipped", { why: "client_gone" });
    return "skipped";
  }
  // T7: only a proposal or estimate is ever redacted; the check stays with the others so no copy is made from a redacted row.
  if (row.redacted) {
    logEvent("pdf.supplier_skipped", { why: "redacted" });
    return "skipped";
  }
  // The original's PDF comes first (it is made from the same envelope): until then there is nothing to copy; the original's own render sends this message again once it is stored.
  if (row.pdf_sha256 === null || row.snapshot_r2_key === null) {
    logEvent("pdf.supplier_skipped", { why: "original_not_ready" });
    return "skipped";
  }
  const envelopeObject = await env.DOCS.get(row.snapshot_r2_key);
  if (envelopeObject === null) throw new Error("the envelope object is missing");
  return renderInvoice(env, msg, row, await envelopeObject.text(), now, clock, htmlOf, "supplier");
}

/** Asks for a document's supplier copy (one message; a queue that fails is the caller's to log: the admin download asks again on demand). */
export async function enqueueSupplierCopy(env: Pick<Env, "PDF_QUEUE">, documentId: string): Promise<void> {
  await env.PDF_QUEUE.send({ v: 1, kind: "pdf.supplier", documentId, hop: 0 } satisfies PdfSupplierMessage);
}

const GONE_SQL = "SELECT 1 AS gone FROM clients WHERE id = ?1 AND anonymised_at IS NOT NULL";
async function clientIsGone(env: Env, clientId: string): Promise<boolean> {
  return (await env.DB.prepare(GONE_SQL).bind(clientId).first()) !== null;
}

const REDACTED_SQL = "SELECT 1 AS redacted FROM documents WHERE id = ?1 AND redacted_at IS NOT NULL";
/** T7: whether the offer's personal details were erased (Settled by the lead on the safest reading, 2026-10-30 (08-C RB-37)). Read only when a write matched nothing. */
async function isRedacted(env: Env, documentId: string): Promise<boolean> {
  return (await env.DB.prepare(REDACTED_SQL).bind(documentId).first()) !== null;
}

function skip(why: string): SnapshotOutcome {
  logEvent("pdf.snapshot_skipped", { why });
  return "skipped";
}

// ---- render ----------------------------------------------------------------------------------------------------------------------------

type RenderRow = {
  id: string;
  type: string;
  frozen_at: number | null;
  fy: string | null;
  number: number | null;
  number_display: string | null;
  version: number;
  snapshot_r2_key: string | null;
  snapshot_sha256: string | null;
  pdf_sha256: string | null;
  client_gone: number;
  /** T7: 1 once the offer's personal details were erased (never rendered again). */
  redacted: number;
};

export const RENDER_ROW_SQL = `SELECT id, type, frozen_at, fy, number, number_display, version, snapshot_r2_key, snapshot_sha256, pdf_sha256,
  EXISTS (SELECT 1 FROM clients c WHERE c.id = documents.client_id AND c.anonymised_at IS NOT NULL) AS client_gone,
  redacted_at IS NOT NULL AS redacted
  FROM documents WHERE id = ?1`;

/** The view of an envelope as this Worker prints it: the acceptance box names the host of `PORTAL_URL` (07-P §1). */
export const viewOf = (env: Pick<Env, "PORTAL_URL">, envelope: Envelope): PdfView =>
  toPdfView(envelope, viewConfigFor(env.PORTAL_URL));

export type RenderOutcome = "rendered" | "adopted" | "delayed" | "skipped" | "refused" | "resnapshot";

/**
 * What the rest of the system learns when a PDF is stored (M4.5). A document's PDF queues the offer emails that were waiting for it; an
 * acceptance certificate queues the confirmation emails. Both are idempotent, and both are called again when a redelivery finds the work
 * already done, so an `onRendered` that failed once is completed by the retry.
 */
export type RenderedEvent =
  | { kind: "document"; documentId: string }
  | { kind: "certificate"; acceptanceId: string };
export async function onRendered(env: Env, event: RenderedEvent): Promise<void> {
  if (event.kind === "document") await queueWaitingSends(env, event.documentId);
  else await queueAcceptedConfirmation(env, event.acceptanceId);
}

export const dayOf = (now: number) => utcDateOf(now);

/** Saves a stored PDF on the row once, and counts the render in the statistics when the browser did the work. */
async function settle(
  env: Env,
  row: RenderRow,
  pdfKey: string,
  pdfSha256: string,
  usage: { renders: number; browserMs: number },
  now: number,
): Promise<void> {
  const date = dayOf(now);
  const statements = [
    env.DB.prepare(
      "UPDATE documents SET pdf_r2_key = ?2, pdf_sha256 = ?3 WHERE id = ?1 AND pdf_sha256 IS NULL AND redacted_at IS NULL",
    ).bind(row.id, pdfKey, pdfSha256),
  ];
  if (usage.renders > 0) {
    statements.push(
      stat(env, date, "pdf.renders", usage.renders, now),
      stat(env, date, "pdf.browser_ms", usage.browserMs, now),
      env.DB.prepare(HALF_BELL_SQL).bind(date, BROWSER_ALERT_MS, BELL_COPY.half),
    );
  }
  const [saved] = await env.DB.batch(statements);
  // T7: redacted while it was being rendered: the PDF just stored is deleted, and no email follows (Settled by the lead on the safest reading, 2026-10-30 (08-C RB-37)).
  if (saved?.meta.changes === 0 && (await isRedacted(env, row.id))) {
    await env.DOCS.delete(pdfKey);
    logEvent("pdf.render_skipped", { why: "redacted" });
    return;
  }
  await onRendered(env, { kind: "document", documentId: row.id });
  // Q11: the supplier's copy follows the original, as its own unit of work (after `onRendered`, so a failed send leaves the client's PDF and its emails untouched).
  if (hasSupplierCopy(row.type)) await enqueueSupplierCopy(env, row.id);
}

/** The page of a document view (the layout). A test passes its own to check the integrity rules whatever the layout prints (LD33). */
export type HtmlOf = (view: Parameters<typeof renderDocumentHtml>[0]) => string;

/** Handles one `pdf.render` message. `clock` is the pacer's (a test passes a fake), `htmlOf` the layout (a test passes a controlled page for an invoice). */
export async function processRender(
  env: Env,
  msg: PdfRenderMessage,
  now = Date.now(),
  clock: Clock = realClock,
  htmlOf: HtmlOf = renderDocumentHtml,
): Promise<RenderOutcome> {
  const row = await env.DB.prepare(RENDER_ROW_SQL).bind(msg.documentId).first<RenderRow>();
  const invoice = row !== null && isInvoiceFlowType(row.type);
  if (!row || row.frozen_at === null || (row.type !== "proposal" && row.type !== "estimate" && !invoice)) {
    logEvent("pdf.render_skipped", { why: row ? "not_supported" : "not_found" });
    return "skipped";
  }
  // T7: an offer whose personal details were erased is never rendered and wakes no send (Settled by the lead on the safest reading, 2026-10-30 (08-C RB-37)).
  if (row.redacted) {
    logEvent("pdf.render_skipped", { why: "redacted" });
    return "skipped";
  }
  if (row.pdf_sha256 !== null) {
    // Done already. A redelivery whose first run stored the PDF but died before `onRendered` completes it here (idempotent).
    await onRendered(env, { kind: "document", documentId: row.id });
    // the supplier copy too (idempotent: a copy already stored is adopted without a render)
    if (hasSupplierCopy(row.type)) await enqueueSupplierCopy(env, row.id);
    logEvent("pdf.render_skipped", { why: "done" });
    return "skipped";
  }
  // Anonymised while the render waited (a quota or rate delay): no PDF, no `onRendered` (the standing rule; Researched 2026-10-28, DPDP Act s.8(7) and s.12(3) (08-C RB-11)).
  if (row.client_gone) {
    logEvent("pdf.render_skipped", { why: "client_gone" });
    return "skipped";
  }
  if (row.snapshot_r2_key === null) {
    // The envelope step has not finished (or its row update was lost): do it again, then the render follows.
    await env.PDF_QUEUE.send({
      v: 1,
      kind: "pdf.snapshot",
      documentId: row.id,
      reason: "retry",
    } satisfies PdfSnapshotMessage);
    return "resnapshot";
  }
  const envelopeObject = await env.DOCS.get(row.snapshot_r2_key);
  if (envelopeObject === null) throw new Error("the envelope object is missing");
  if (invoice) return renderInvoice(env, msg, row, await envelopeObject.text(), now, clock, htmlOf);
  const envelope = parseEnvelope(await envelopeObject.text());
  const verdict =
    envelope === null
      ? ({ ok: false, code: "shape" } as const)
      : envelope.documentId !== row.id || envelope.snapshotSha256 !== row.snapshot_sha256
        ? ({ ok: false, code: "row_mismatch" } as const)
        : await verifyEnvelope(envelope);
  if (!envelope || !verdict.ok) {
    logEvent("pdf.refused", { stage: "render", code: verdict.ok ? "unknown" : verdict.code });
    await env.DB.batch([
      bell(
        env,
        "pdf.failed",
        "document",
        row.id,
        BELL_COPY.integrity(documentLabel(row.number_display)),
        `/proposals/${row.id}`,
      ),
    ]);
    return "refused";
  }
  const keys = pdfKeys({
    type: envelope.type,
    fy: envelope.fy,
    number: envelope.number,
    version: envelope.version,
  });

  // A PDF stored by an earlier run whose row update was lost: the first one stays, a document is never rendered twice.
  const already = await env.DOCS.get(keys.pdf);
  if (already !== null) {
    await settle(
      env,
      row,
      keys.pdf,
      await sha256Bytes(new Uint8Array(await already.arrayBuffer())),
      { renders: 0, browserMs: 0 },
      now,
    );
    logEvent("pdf.adopted", {});
    return "adopted";
  }

  const view = viewOf(env, envelope);
  const result = await renderPaced(env, renderDocumentHtml(view), pdfOptionsFor(view), clock);
  if (!result.ok) return failed(env, msg, result, now);

  const { bytes, sha256 } = await putPdfOnce(env.DOCS, keys.pdf, result.bytes);
  await settle(env, row, keys.pdf, sha256, { renders: 1, browserMs: result.browserMs }, now);
  logEvent("pdf.rendered", { bytes: bytes.byteLength, browserMs: result.browserMs, hop: msg.hop });
  return "rendered";
}

/** A render that did not give a PDF: delay (rate, quota) or throw (anything a retry might fix). */
export async function failed(
  env: Env,
  msg:
    | PdfRenderMessage
    | PdfCertificateMessage
    | PdfStatementMessage
    | PdfSupplierMessage
    | PdfDeedMessage
    | ReceiptRenderMessage,
  result: Exclude<Awaited<ReturnType<typeof renderPaced>>, { ok: true }>,
  now: number,
): Promise<"delayed"> {
  if (result.kind === "rate" || result.kind === "quota") {
    if (msg.hop >= PDF_MAX_HOPS) throw new Error(`pdf: ${result.kind} limit, ${PDF_MAX_HOPS} hops used`);
    let delay: number;
    if (result.kind === "rate") {
      delay = Math.max(result.retryAfterS, 10);
    } else {
      delay = Math.min(MAX_DELAY_S, Math.ceil((nextUtcMidnight(now) + QUOTA_MARGIN_MS - now) / 1000));
      // Counted, and the bell rings once a day (unique per owner, kind and date).
      await env.DB.batch([
        stat(env, dayOf(now), "pdf.quota_hits", 1, now),
        bell(env, "pdf.quota", "system", dayOf(now), BELL_COPY.quota, "/"),
      ]);
    }
    await env.PDF_QUEUE.send({ ...msg, hop: msg.hop + 1 }, { delaySeconds: delay });
    logEvent("pdf.delayed", { kind: result.kind, delay, hop: msg.hop + 1 });
    return "delayed";
  }
  // A refused 2xx answer (damaged, not a PDF) used browser time all the same: counted, with the half-of-the-day bell, before the retry
  // (FX-3 round 3, item 4). The time is the only figure kept; no render is counted.
  const used = "browserMs" in result ? (result.browserMs ?? 0) : 0;
  if (used > 0) {
    const date = dayOf(now);
    await env.DB.batch([
      stat(env, date, "pdf.browser_ms", used, now),
      env.DB.prepare(HALF_BELL_SQL).bind(date, BROWSER_ALERT_MS, BELL_COPY.half),
    ]);
  }
  logEvent("pdf.render_failed", { kind: result.kind });
  throw new Error(`pdf render failed: ${result.kind}`);
}

// ---- certificate ------------------------------------------------------------------------------------------------------------------

export type CertificateOutcome = "rendered" | "adopted" | "delayed" | "skipped";

/**
 * Handles one `pdf.certificate` message (M4.5, ADM-PROP-08). The same paced render as a document (`renderPaced`, `failed`, `putOnce`), so a
 * burst of acceptances and sends never makes more than one Browser Run call per 10 s. The certificate is rendered ONCE: a head before the
 * render, `If-None-Match: *` on the put, `INSERT OR IGNORE` on the row (append-only). Then `onRendered` queues the confirmation emails.
 * The data is the evidence row read in one query, never the live document.
 */
export async function processCertificate(
  env: Env,
  msg: PdfCertificateMessage,
  now = Date.now(),
  clock: Clock = realClock,
): Promise<CertificateOutcome> {
  const read = await readCertificateView(env.DB, msg.acceptanceId);
  if (read === null) {
    logEvent("pdf.certificate_skipped", { why: "no_acceptance" });
    return "skipped";
  }
  if (read.rendered) {
    await onRendered(env, { kind: "certificate", acceptanceId: msg.acceptanceId });
    logEvent("pdf.certificate_skipped", { why: "done" });
    return "skipped";
  }
  const insert = (sha: string, stats?: { browserMs: number }) => {
    const date = dayOf(now);
    const statements = [
      env.DB.prepare(
        "INSERT OR IGNORE INTO acceptance_certificates (acceptance_id, r2_key, sha256, rendered_at) VALUES (?1, ?2, ?3, ?4)",
      ).bind(msg.acceptanceId, read.key, sha, now),
    ];
    if (stats) {
      statements.push(
        stat(env, date, "pdf.renders", 1, now),
        stat(env, date, "pdf.browser_ms", stats.browserMs, now),
        env.DB.prepare(HALF_BELL_SQL).bind(date, BROWSER_ALERT_MS, BELL_COPY.half),
      );
    }
    return env.DB.batch(statements);
  };

  // A certificate stored by an earlier run whose row write was lost: the first one stays, an acceptance never gets two.
  const already = await env.DOCS.get(read.key);
  if (already !== null) {
    await insert(await sha256Bytes(new Uint8Array(await already.arrayBuffer())));
    await onRendered(env, { kind: "certificate", acceptanceId: msg.acceptanceId });
    logEvent("pdf.certificate_adopted", {});
    return "adopted";
  }

  const result = await renderPaced(
    env as unknown as RenderEnv,
    renderCertificateHtml(read.view),
    pdfOptionsFor(),
    clock,
  );
  if (!result.ok) return failed(env, msg, result, now);
  const { bytes, sha256 } = await putPdfOnce(env.DOCS, read.key, result.bytes);
  await insert(sha256, { browserMs: result.browserMs });
  await onRendered(env, { kind: "certificate", acceptanceId: msg.acceptanceId });
  logEvent("pdf.certificate_rendered", {
    bytes: bytes.byteLength,
    browserMs: result.browserMs,
    hop: msg.hop,
  });
  return "rendered";
}

// ---- sweep -----------------------------------------------------------------------------------------------------------------------------

/** After this many IST days on which a document's PDF message ran out of tries, the nightly sweep stops trying it (FX-1, A6 2) and the owners get one `pdf.refused` bell. */
export const SWEEP_MAX_FAILED_NIGHTS = 3;

/**
 * The sweep's pick (`?1` the newest `frozen_at` it may take). Exported so a test can EXPLAIN it: it must use `documents_pdf_pending` (the pending set is small; the
 * order is then a sort of that set). FX-1 (A6 2): the least recently tried first (`pdf_failures.last_attempt_at`, never tried counts as 0), then the oldest; a
 * document with `SWEEP_MAX_FAILED_NIGHTS` failed nights is left out, as is one with a refusal bell.
 */
export const SWEEP_SQL = `SELECT documents.id FROM documents INDEXED BY documents_pdf_pending LEFT JOIN pdf_failures f ON f.document_id = documents.id
  WHERE documents.frozen_at IS NOT NULL AND documents.pdf_sha256 IS NULL AND documents.type IN ('proposal', 'estimate', 'tax_invoice', 'export_invoice', 'proforma', 'credit_note', 'debit_note') AND documents.frozen_at <= ?1
    AND coalesce(f.nights, 0) < ${SWEEP_MAX_FAILED_NIGHTS} AND documents.redacted_at IS NULL
    AND NOT EXISTS (SELECT 1 FROM clients z WHERE z.id = documents.client_id AND z.anonymised_at IS NOT NULL)
    AND NOT EXISTS (SELECT 1 FROM notifications r WHERE r.entity_type = 'document' AND r.entity_id = documents.id AND r.kind = 'pdf.refused')
  ORDER BY coalesce(f.last_attempt_at, 0), documents.frozen_at, documents.id LIMIT ${SWEEP_LIMIT}`;

/** The sweep's note that it tried a document (`?1` the document, `?2` the sweep's time). One row per document; the failed nights are left as they are. */
export const SWEEP_ATTEMPT_SQL = `INSERT INTO pdf_failures (document_id, nights, last_attempt_at) VALUES (?1, 0, ?2)
  ON CONFLICT (document_id) DO UPDATE SET last_attempt_at = excluded.last_attempt_at`;

/**
 * Handles one `pdf.sweep` message: enqueues a snapshot for each sent document that still has no PDF (at most 20 per run), then records the attempt on each (one
 * batch), so tomorrow's sweep starts with the ones it tried least recently. The messages go first: a lost attempt row only changes the order, never loses a PDF.
 */
export async function processSweep(env: Env, msg: PdfSweepMessage): Promise<number> {
  const { results } = await env.DB.prepare(SWEEP_SQL)
    .bind(msg.asOf - SWEEP_GRACE_MS)
    .all<{ id: string }>();
  if (results.length > 0) {
    await env.PDF_QUEUE.sendBatch(
      results.map((r) => ({
        body: { v: 1, kind: "pdf.snapshot", documentId: r.id, reason: "sweep" } satisfies PdfSnapshotMessage,
      })),
    );
    await env.DB.batch(results.map((r) => env.DB.prepare(SWEEP_ATTEMPT_SQL).bind(r.id, msg.asOf)));
  }
  logEvent("pdf.sweep", { picked: results.length });
  return results.length;
}

/**
 * A night on which the document's PDF message ran out of tries (`?1` the document, `?2` the IST day, `?3` the time): counted once per IST day (a second dead letter
 * of the same day, a snapshot and then a render, adds nothing).
 */
export const FAILED_NIGHT_SQL = `INSERT INTO pdf_failures (document_id, nights, last_failed_day, last_attempt_at) VALUES (?1, 1, ?2, ?3)
  ON CONFLICT (document_id) DO UPDATE SET nights = nights + CASE WHEN last_failed_day IS excluded.last_failed_day THEN 0 ELSE 1 END,
    last_failed_day = excluded.last_failed_day, last_attempt_at = max(coalesce(last_attempt_at, 0), excluded.last_attempt_at)`;

/** The owners' one `pdf.refused` bell once a document reaches `SWEEP_MAX_FAILED_NIGHTS` (`?1` the document, `?2` the title, `?3` the link): unique per owner, kind and document. */
export const STOPPED_BELL_SQL = `INSERT OR IGNORE INTO notifications (id, user_id, kind, entity_type, entity_id, title, link)
  SELECT 'n_' || lower(hex(randomblob(16))), u.id, 'pdf.refused', 'document', ?1, ?2, ?3 FROM staff_users u
  WHERE u.status = 'active' AND u.role = 'owner' AND (SELECT nights FROM pdf_failures WHERE document_id = ?1) >= ${SWEEP_MAX_FAILED_NIGHTS}`;

/** The cron's one job for PDFs: enqueue ONE sweep message. No D1 read. */
export async function enqueueSweep(env: Env, scheduledTime: number): Promise<void> {
  // One `sendBatch` of two messages (still one queue operation): the PDF sweep (M4.4) and the offer sweep (M4.5).
  await env.PDF_QUEUE.sendBatch([
    { body: { v: 1, kind: "pdf.sweep", asOf: scheduledTime } satisfies PdfSweepMessage },
    { body: { v: 1, kind: "offer.sweep", asOf: scheduledTime } satisfies OfferSweepMessage },
  ]);
}

// ---- the queues ------------------------------------------------------------------------------------------------------------------------

/** Routes one message of the PDF queue. A body this version cannot use is logged and acknowledged (a retry cannot help). */
export async function processPdf(
  env: Env,
  body: unknown,
  now = Date.now(),
  clock: Clock = realClock,
): Promise<void> {
  if (!isPdfMessage(body)) {
    logEvent("pdf.unknown");
    return;
  }
  if (body.kind === "pdf.snapshot") await processSnapshot(env, body);
  else if (body.kind === "pdf.render") await processRender(env, body, now, clock);
  else if (body.kind === "pdf.certificate") await processCertificate(env, body, now, clock);
  else if (body.kind === "pdf.supplier") await processSupplierCopy(env, body, now, clock);
  else if (body.kind === "offer.sweep") await processOfferSweep(env, body);
  // M5.5b: a statement PDF is routed by `handleQueue` to `statement-pdf.ts` before it reaches here (that file imports this one); a message that does arrive is acknowledged and logged.
  else if (body.kind === "pdf.statement") logEvent("pdf.statement_misrouted");
  // T11: a deed's PDF is routed by `handleQueue` to `deed-pdf.ts` the same way (that file imports this one).
  else if (body.kind === "pdf.deed") logEvent("pdf.deed_misrouted");
  else await processSweep(env, body);
}

/**
 * A PDF message that ran out of tries: the owners are told (once per document and kind), and the next daily sweep picks the document up
 * again. A sweep that ran out of tries is only logged: tomorrow's cron enqueues another.
 */
export async function processPdfDeadLetter(env: Env, body: unknown, now = Date.now()): Promise<void> {
  if (isPdfMessage(body) && body.kind === "pdf.certificate") {
    // The acceptance is safe (its evidence row is written); only the certificate file is missing. The owners are told, the sweep tries again.
    // The bell is unique per (user, kind, entity), so the entity carries the IST day: a failure on a later day (the sweep's retry) rings again,
    // a redelivery on the same day does not.
    await env.DB.batch([
      bell(
        env,
        "pdf.failed",
        "acceptance",
        `${body.acceptanceId}:${todayIst(now)}`,
        "An acceptance certificate couldn't be made. We'll try again tonight.",
        "/",
      ),
    ]);
  } else if (isPdfMessage(body) && (body.kind === "pdf.snapshot" || body.kind === "pdf.render")) {
    const row = await env.DB.prepare(
      `SELECT type, number_display, version,
        EXISTS (SELECT 1 FROM clients c WHERE c.id = documents.client_id AND c.anonymised_at IS NOT NULL) AS client_gone,
        redacted_at IS NOT NULL AS redacted
        FROM documents WHERE id = ?1`,
    )
      .bind(body.documentId)
      .first<{
        type: string;
        number_display: string | null;
        version: number;
        client_gone: number;
        redacted: number;
      }>();
    // No bell for an anonymised client: nothing is left to try again.
    if (row?.client_gone) {
      logEvent("pdf.dead_letter", { kind: body.kind, skipped: "client_gone" });
      return;
    }
    // T7: nor for an offer whose personal details were erased: it is never made again (Settled by the lead on the safest reading, 2026-10-30 (08-C RB-37)).
    if (row?.redacted) {
      logEvent("pdf.dead_letter", { kind: body.kind, skipped: "redacted" });
      return;
    }
    // An invoice has one version and its own page: no "v1", and the link is the invoice's.
    const invoice = row !== null && isInvoiceFlowType(row.type);
    const link = invoice ? `/invoices/${body.documentId}` : `/proposals/${body.documentId}`;
    await env.DB.batch([
      bell(
        env,
        "pdf.failed",
        "document",
        body.documentId,
        invoice
          ? BELL_COPY.failedInvoice(row.number_display ?? "this invoice")
          : BELL_COPY.failed(row?.number_display ?? "this document", row?.version ?? 1),
        link,
      ),
      // FX-1 (A6 2): the failed night is counted, and at the third the sweep stops and the owners are told once.
      ...(row
        ? [
            env.DB.prepare(FAILED_NIGHT_SQL).bind(body.documentId, todayIst(now), now),
            env.DB.prepare(STOPPED_BELL_SQL).bind(
              body.documentId,
              BELL_COPY.stoppedNightly(documentLabel(row.number_display)),
              link,
            ),
          ]
        : []),
    ]);
  }
  // A supplier copy that ran out of tries rings no bell (decided, 07-W §5.7, and nothing is lost: the original is made, and the Owner's or Accountant's download asks for the copy
  // again on demand); it is logged below.
  logEvent("pdf.dead_letter", { kind: isPdfMessage(body) ? body.kind : "unknown" });
}
