// Sending: the SES v2 client (SigV4 via aws4fetch, docs/05 §11.1) and the `log` transport used locally and in tests.
// A send ends in one of three ways, so a queue consumer knows what to do:
//   sent      accepted (SES message id)
//   permanent a 4xx other than throttling: log `failed` and acknowledge, retrying cannot help
//   retry     throttling, 5xx or a network error: let the queue redeliver
import { AwsClient, AwsV4Signer } from "aws4fetch";
import { allowedHeaders, emailTags, formatAddress, headerValue } from "./headers.ts";

/** One file on an email (SES v2 `Simple.Attachments`, confirmed in the SES developer guide): the bytes, a safe file name, a type. */
export type Attachment = { fileName: string; contentType: string; bytes: Uint8Array };

/**
 * Base64 of bytes. Uses the native `Uint8Array.prototype.toBase64` where the runtime has it (fast, no string building) and
 * falls back to `btoa` over 32 KB chunks, so a large PDF never builds one huge argument list.
 */
export function toBase64(bytes: Uint8Array): string {
  const native = (bytes as Uint8Array & { toBase64?: () => string }).toBase64;
  if (typeof native === "function") return native.call(bytes);
  let out = "";
  const step = 0x8000;
  for (let i = 0; i < bytes.length; i += step) {
    out += String.fromCharCode(...bytes.subarray(i, i + step));
  }
  return btoa(out);
}

/** True when this runtime has the native `Uint8Array.prototype.toBase64`. Without it, base64 costs about 37 ms per MB (Node, measured), so callers send link-only. */
export const hasNativeBase64 = (): boolean =>
  typeof (Uint8Array.prototype as { toBase64?: unknown }).toBase64 === "function";

export type SendInput = {
  /** Display name + address; the name is quoted and stripped of control characters. */
  from: { name?: string; address: string };
  to: string;
  replyTo?: string;
  subject: string;
  html: string;
  text: string;
  /** Optional files (M4.5: the proposal PDF). Absent for every other email. */
  attachments?: Attachment[];
  /**
   * M7.2 (C.4, ADM-MAIL-03): extra headers, from an allow-list only (`List-Unsubscribe`, `List-Unsubscribe-Post`; any other name is dropped), each value through
   * `headerValue`. SES v2 `Content.Simple.Headers` (CONFIRMED, SES API v2 `SendEmail` request syntax and the "Send email with custom headers" example).
   */
  headers?: Record<string, string>;
  /** M7.2: this email's configuration set (the digest's `techaust-marketing`, docs/05 §11.1), else the transport's own. */
  configurationSet?: string;
  /**
   * M7.2 (L6): message tags, `env` on every send (SES v2 `EmailTags`, CONFIRMED; values only ASCII letters, digits, `_` and `-`, at most 256: CONFIRMED, SES API v2
   * `MessageTag`). The SES hook applies an event only when its `env` tag is this Worker's `ENVIRONMENT` (one AWS account sends for staging and production).
   */
  tags?: { env: string };
};

export type SendResult =
  | { kind: "sent"; messageId: string }
  | { kind: "permanent"; error: string }
  | { kind: "retry"; error: string };

export type Transport = { send(input: SendInput): Promise<SendResult> };

export type SesConfig = {
  accessKeyId: string;
  secretAccessKey: string;
  region: string;
  configurationSet?: string;
};

const THROTTLE_CODES = [
  "Throttling",
  "TooManyRequests",
  "RequestLimitExceeded",
  "SlowDown",
  "ServiceUnavailable",
];

/**
 * Derived SigV4 signing keys, shared by every client made in this isolate. aws4fetch keeps the key (one per secret, day,
 * region and service) in the `cache` it is given, but the consumer makes a new transport for each message, so without
 * this shared map each email would repeat the four HMACs of the derivation. A new day derives a new key (the date is part
 * of aws4fetch's cache key), so an old key is never reused.
 */
const SIGNING_KEYS = new Map<string, ArrayBuffer>();

/**
 * The one SES client set-up, shared by `sesTransport` and `primeSesSigning` so both use the same cache key (secret, day,
 * region, service) and the prime keeps helping after an edit.
 */
function sesClient(config: SesConfig): AwsClient {
  // one entry per day, region and secret: cap the map at 8 entries, clearing it when it grows past that
  if (SIGNING_KEYS.size > 8) SIGNING_KEYS.clear();
  return new AwsClient({
    accessKeyId: config.accessKeyId,
    secretAccessKey: config.secretAccessKey,
    service: "ses",
    region: config.region,
    retries: 0, // the queue retries (one unit of work per message)
    cache: SIGNING_KEYS,
  });
}

const sesUrl = (region: string) => `https://email.${region}.amazonaws.com/v2/email/outbound-emails`;

/** The SES v2 `SendEmail` call (JSON, SigV4 for service `ses`). */
export function sesTransport(config: SesConfig): Transport {
  const client = sesClient(config);
  const url = sesUrl(config.region);
  return {
    async send(input) {
      let body: string;
      try {
        const headers = allowedHeaders(input.headers);
        const tags = emailTags(input.tags);
        const configurationSet = input.configurationSet || config.configurationSet;
        body = JSON.stringify({
          FromEmailAddress: formatAddress(input.from.name, input.from.address),
          Destination: { ToAddresses: [formatAddress(undefined, input.to)] },
          ...(input.replyTo ? { ReplyToAddresses: [formatAddress(undefined, input.replyTo)] } : {}),
          Content: {
            Simple: {
              Subject: { Data: headerValue(input.subject), Charset: "UTF-8" },
              Body: {
                Html: { Data: input.html, Charset: "UTF-8" },
                Text: { Data: input.text, Charset: "UTF-8" },
              },
              ...(input.attachments?.length
                ? {
                    Attachments: input.attachments.map((a) => ({
                      RawContent: toBase64(a.bytes),
                      FileName: a.fileName,
                      ContentType: a.contentType,
                      ContentDisposition: "ATTACHMENT",
                      ContentTransferEncoding: "BASE64",
                    })),
                  }
                : {}),
              ...(headers.length ? { Headers: headers } : {}),
            },
          },
          ...(configurationSet ? { ConfigurationSetName: configurationSet } : {}),
          ...(tags.length ? { EmailTags: tags } : {}),
        });
      } catch (e) {
        // An address that cannot be formatted can never be sent: permanent.
        return { kind: "permanent", error: e instanceof Error ? e.message : "invalid message" };
      }
      let res: Response;
      try {
        res = await client.fetch(url, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body,
          signal: AbortSignal.timeout(8_000),
        });
      } catch {
        return { kind: "retry", error: "network error" };
      }
      const raw = await res.text().catch(() => "");
      let parsed: { MessageId?: string; message?: string; Message?: string; __type?: string } = {};
      try {
        parsed = JSON.parse(raw);
      } catch {
        // not JSON: keep the status only
      }
      if (res.ok) return { kind: "sent", messageId: parsed.MessageId ?? "" };
      const type = (res.headers.get("x-amzn-ErrorType") ?? parsed.__type ?? "").split(":")[0] ?? "";
      // Error text from SES names the problem, never the recipient's message; keep it short.
      const error = `${res.status} ${type}`.trim().slice(0, 200);
      const throttled = res.status === 429 || THROTTLE_CODES.some((c) => type.includes(c));
      if (throttled || res.status >= 500) return { kind: "retry", error };
      return { kind: "permanent", error };
    },
  };
}

/**
 * Primes the SES path in an isolate that is about to send (CPU tuning 4): derives the day's signing key into the shared
 * `SIGNING_KEYS` map and builds one `Request`, by signing a made-up body with the REAL credentials. Nothing is sent, nothing
 * is logged, and the secret goes nowhere but the signer. A caller that has `env` and expects email to follow (the staff
 * alert expansion) calls it so the first real send finds the key derived. Resolves true when the signing worked; never throws.
 */
export async function primeSesSigning(config: SesConfig): Promise<boolean> {
  try {
    const signed = await sesClient(config).sign(sesUrl(config.region), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: "{}",
    });
    return signed.headers.has("authorization");
  } catch {
    return false;
  }
}

/** The warm-up's made-up credentials (exported for the test that proves the shared key map stays untouched). */
export const WARM_KEY_ID = "AKIAWARMUP00000000";
export const WARM_SECRET = "warm-up-not-a-secret";

/**
 * Start-up warm-up of the SES path (CPU tuning round 2): signs one made-up request with made-up credentials and its own
 * key cache, so the first real email in an isolate does not pay for the first `crypto.subtle` import, HMAC and digest and
 * the JSON build. Nothing is sent and nothing is stored (no `fetch`, not the shared SIGNING_KEYS map); the credentials
 * are fixed dummies, never `env`. It uses `AwsV4Signer` directly, with no `Request` and no `AbortSignal`: workerd refuses
 * both in a Worker's global scope ("Disallowed operation called within global scope"), while Web Crypto is allowed there.
 * (`Date` reads 0 during start-up, so this signs a 1970 date: harmless, the key cache is its own.) Resolves true when the
 * signing worked.
 */
export async function warmSesSigning(): Promise<boolean> {
  try {
    const body = JSON.stringify({
      FromEmailAddress: formatAddress("Warm", "warm@warm-up.invalid"),
      Destination: { ToAddresses: [formatAddress(undefined, "warm@warm-up.invalid")] },
      Content: {
        Simple: {
          Subject: { Data: "warm", Charset: "UTF-8" },
          Body: { Text: { Data: "warm", Charset: "UTF-8" } },
        },
      },
    });
    const signed = await new AwsV4Signer({
      url: "https://email.ap-south-1.amazonaws.com/v2/email/outbound-emails",
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body,
      accessKeyId: WARM_KEY_ID,
      secretAccessKey: WARM_SECRET,
      service: "ses",
      region: "ap-south-1",
      cache: new Map(),
    }).sign();
    return signed.headers.has("authorization");
  } catch {
    return false;
  }
}

/** Local and test transport: nothing leaves the machine and nothing personal is printed. */
export function logTransport(log: (line: string) => void = console.log): Transport {
  return {
    async send(input) {
      const messageId = `log-${crypto.randomUUID()}`;
      log(JSON.stringify({ msg: "email.log_transport", messageId, subjectChars: input.subject.length }));
      return { kind: "sent", messageId };
    },
  };
}
