// The email templates the system knows (docs/05 §11.1). A plain list in its own file so code that only needs the names (the
// settings schemas, the admin Worker) does not pull in the queue-message schemas and classic zod with them.
export const EMAIL_TEMPLATES = [
  "lead.acknowledgement",
  "lead.alert",
  // M2.4b: the client portal's sign-in link and the staff security emails (ADM-MAIL-01)
  "portal.magic_link",
  "staff.new_device",
  "staff.2fa_change",
  "staff.lockout",
  "staff.lockout_owner",
  // M3.1: the invitation to join the admin (ADM-AUTH-07, ADM-MAIL-01; body in 07-H)
  "staff.invite",
  // M3.2: a reply written on the lead page (ADM-LEAD-06; the starting texts are in 07-I)
  "lead.reply",
  // M4.5: a proposal or estimate sent, its acceptance (to the client and to TecHaust) and the approval emails (07 §8)
  "offer.sent",
  "offer.accepted.client",
  "offer.accepted.staff",
  "offer.declined.staff",
  "approval.requested",
  "approval.decided",
  // M5.4: an invoice, proforma, credit note or debit note sent to the client (ADM-INV-15), the payment reminder (ADM-INV-13; one template, the offset and
  // the kind are in its data) and the owners' alerts: unbilled work (ADM-INV-19), a proforma for delivered work still unpaid (ADM-INV-10), the LUT letter (ADM-INV-18).
  // The words are 07-U's (the designer builds the templates; the data keys are `INVOICE_EMAIL_DATA` in invoice-email.ts).
  "invoice.sent",
  "proforma.sent",
  "credit_note.sent",
  "debit_note.sent",
  "reminder.sent",
  "alert.unbilled",
  "alert.proforma_due",
  "lut.reminder",
  // M5.5b: the owners' monthly Export Declaration Form reminder (ADM-REP-07, Q55) and the export realisation alerts, one template for the
  // four stages (the stage is in its data; ADM-REP-07, Q54). The words are 07-V's; the designer builds them (a plain stub until then, LD88).
  "edf.reminder",
  "realisation.alert",
  // T11: the signed deed of assignment is in the client's portal (to its portal contacts). Words: 07-ZJ lines 8 to 11 (approved by the lead under the
  // owner's delegation, 2026-11-01).
  "deed.signed",
  // M6.5 (ADM-MAIL-01, ADM-PAY-09): the client's payment receipt (from billing@, to its portal contacts who can see finance). Words: 07-ZO lines 11 and 12.
  "receipt.sent",
  // M7.2 (ADM-MAIL-01, ADM-G-09, ADM-PAY-08, JOB-CRON-03): the owners' weekly digest (the only non-transactional email), a staff notification email (one per
  // bell row, by the member's switches), the client's refund email (Q4 A) and the unfinished sign-in alert (Q3 A). Words: 07-ZQ (`@techaust/core/copy-zq`).
  "digest.weekly",
  "staff.notification",
  "refund.sent",
  "staff.signin_unfinished",
  // M7.4 (D.8, L32; POR-11): the acknowledgement of a request sent from the portal (07-ZR C2 to C4 and the Rule 9 block; the builder's plain template).
  "request.received",
] as const;
export type EmailTemplate = (typeof EMAIL_TEMPLATES)[number];

/**
 * M7.2 (C.4, L8, L16): the non-transactional emails, which alone carry the RFC 8058 one-click headers, the "Why you're receiving this" footer and the marketing
 * configuration set. Pinned to the staff weekly digest: no marketing email goes to a client in M7.2 (Researched 2026-10-28, DPDP Act s.6 consent and the
 * CAN-SPAM opt-out for commercial email (08-C RB-28); the digest goes to staff only).
 */
export const NON_TRANSACTIONAL_TEMPLATES: readonly string[] = ["digest.weekly"];
export const isNonTransactional = (template: string): boolean =>
  NON_TRANSACTIONAL_TEMPLATES.includes(template);
